const enfermedadData=[{"disease":"La misión a la medida lleva cuatro meses y va por la quinta ronda de cambios","characteristic":"No se contaron las rondas de cambios dentro del alcance","opts":["No se contaron las rondas de cambios dentro del alcance","El cliente resultó difícil","El precio de L 4.500 quedó bajo","Faltó ponerle fecha de entrega"]},{"disease":"Se cobró L 125 por aula a una red y ahora nadie quiere pagar L 250","characteristic":"Se bajó el precio sin quitar alcance, y el descuento se volvió el precio nuevo","opts":["Se bajó el precio sin quitar alcance, y el descuento se volvió el precio nuevo","Los clientes hablan entre ellos","El precio de lista siempre estuvo muy alto","Faltó firmar un contrato con la red"]},{"disease":"Todo el mundo usa el material y no paga nadie","characteristic":"El escalón gratis alcanza para el año entero: dejó de ser prueba y pasó a ser el producto","opts":["El escalón gratis alcanza para el año entero: dejó de ser prueba y pasó a ser el producto","Falta publicidad","El precio es caro para una maestra","Aquí nadie paga por material educativo"]},{"disease":"Se entregó a tiempo y el centro reclamó que faltaban cosas","characteristic":"El «no incluye» no estaba escrito, así que cada quien entendió lo que quiso","opts":["El «no incluye» no estaba escrito, así que cada quien entendió lo que quiso","El centro cambió de opinión a mitad de camino","Se entregó en el formato equivocado","El precio incluía demasiadas cosas"]},{"disease":"La ficha se puso a L 200 y no la compró nadie","characteristic":"El precio salió de sumar las horas de trabajo, no de lo que vale para quien paga","opts":["El precio salió de sumar las horas de trabajo, no de lo que vale para quien paga","El tema de la ficha se pide poco","Hacía falta un logo más serio","No se hizo suficiente publicidad"]},{"disease":"La directora ofreció L 500 al mes por seis aulas y ya no hubo cómo subir","characteristic":"Ella dijo la primera cifra: el ancla quedó de su lado","opts":["Ella dijo la primera cifra: el ancla quedó de su lado","Es un centro con poco presupuesto","Faltó enseñarle todo lo que incluye","Se debió negociar en persona y no por teléfono"]}];
let enferIdx=0,enferDone=false;
function showEnfer(){enferDone=false;if(enferIdx>=enfermedadData.length){const el=document.getElementById('enferDisease');if(el)el.textContent='🎉 ¡Completado!';const opts=document.getElementById('enferOpts');if(opts)opts.innerHTML='';return;}const d=enfermedadData[enferIdx];const prog=document.getElementById('enferProg');if(prog)prog.textContent=`${enferIdx+1} de ${enfermedadData.length}`;const dis=document.getElementById('enferDisease');if(dis)dis.textContent=d.disease;const opts=document.getElementById('enferOpts');if(!opts)return;opts.innerHTML='';_shuffle([...d.opts]).forEach(opt=>{const b=document.createElement('button');b.className='qz-opt';b.textContent=opt;b.onclick=()=>checkEnfer(opt,b,d);opts.appendChild(b);});const fbEl=document.getElementById('fbEnfer');if(fbEl)fbEl.classList.remove('show');}
function checkEnfer(opt,btn,d){if(enferDone)return;enferDone=true;document.querySelectorAll('#enferOpts .qz-opt').forEach(b=>{if(b.textContent===d.characteristic)b.classList.add('correct');else if(b===btn&&b.textContent!==d.characteristic)b.classList.add('wrong');});const isOk=opt===d.characteristic;if(isOk){fb('fbEnfer','¡Correcto! +3 XP',true);if(!xpTracker.wgt.has('enfer_'+enferIdx)){xpTracker.wgt.add('enfer_'+enferIdx);pts(3);}sfx('ok');}else{fb('fbEnfer','Correcto: '+d.characteristic,false);sfx('no');}setTimeout(()=>{enferIdx++;showEnfer();},1800);}
function resetEnfer(){sfx('click');enferIdx=0;showEnfer();}

// ===================== TASK GENERATOR =====================
const identifyTaskDB=[{"s":"Lo que alguien recuerda cuando uno no está.","type":"Promesa"},{"s":"Lo que alguien recibe a cambio de un pago.","type":"Oferta"},{"s":"El objeto del que se comprueba que llegó.","type":"Entregable"},{"s":"Hasta dónde llega lo que se entrega.","type":"Alcance"},{"s":"La lista de lo que queda fuera del precio.","type":"No incluye"},{"s":"La fecha de entrega y qué pasa si se atrasa.","type":"Plazo"},{"s":"Lo que cuesta producir: el mínimo, nunca el precio.","type":"Costo piso"},{"s":"Lo que se puede abrir y comprobar antes de pagar.","type":"Prueba"},{"s":"Qué pasa si no sirve, con plazo escrito.","type":"Salida"},{"s":"La primera cifra que se dice y condiciona las demás.","type":"Ancla de precio"}];
const classifyTaskDB=[{"w":"Tu clase del lunes lista","gen":"Mensaje","n":"Se recuerda","g":"Promesa","t":"No se entrega: se cumple"},{"w":"Ficha de 10 páginas por L 30","gen":"Mensaje","n":"Se cobra","g":"Oferta","t":"Se entrega y se comprueba"},{"w":"La ficha en PDF con su pauta","gen":"Alcance","n":"Dentro","g":"Sí incluye","t":"Va dentro del precio"},{"w":"Imprimir las copias del aula","gen":"Alcance","n":"Fuera","g":"No incluye","t":"Tiene precio aparte"},{"w":"Le ahorra cuatro noches al mes","gen":"Cifra","n":"Del que paga","g":"Valor","t":"De aquí sale el precio"},{"w":"Me llevó doce horas hacerla","gen":"Cifra","n":"Del que cobra","g":"Costo","t":"Solo marca el piso"},{"w":"Una ficha suelta, L 30","gen":"Cobro","n":"Puntual","g":"Por unidad","t":"La compra se decide sola"},{"w":"Un aula al mes, L 250","gen":"Cobro","n":"Repetido","g":"Suscripción","t":"El problema vuelve cada semana"},{"w":"Misión a la medida, L 4.500","gen":"Cobro","n":"Una sola vez","g":"Proyecto cerrado","t":"Alcance fijo y cambios contados"},{"w":"Devolución a los 30 días","gen":"Riesgo","n":"Lo carga quien cobra","g":"Salida","t":"Quita el miedo de la primera compra"}];
const completeTaskDB=[{"s":"Lo que alguien recibe a cambio de un pago es la ___.","opts":["marca","oferta","promesa"],"ans":"oferta"},{"s":"La lista de lo que queda fuera del precio es el ___.","opts":["no incluye","plazo","alcance"],"ans":"no incluye"},{"s":"El costo marca el ___ y nunca el precio.","opts":["techo","margen","piso"],"ans":"piso"},{"s":"La primera cifra que se dice es el ___.","opts":["descuento","ancla","presupuesto"],"ans":"ancla"},{"s":"Qué pasa si no sirve se escribe en la ___.","opts":["prueba","promesa","salida"],"ans":"salida"},{"s":"El aula al mes se cobra por ___.","opts":["suscripción","unidad","proyecto"],"ans":"suscripción"},{"s":"El escalón gratis sirve para probar sin ___.","opts":["cuenta","riesgo","pagar"],"ans":"riesgo"},{"s":"Se baja el precio ___ alcance.","opts":["quitando","regalando","sumando"],"ans":"quitando"}];
const explainQuestions=[{"q":"Explica la diferencia entre la promesa y la oferta, y por qué con una sola no alcanza.","ans":"La promesa es lo que alguien recuerda del proyecto cuando uno no está: «esto me salva la clase del lunes». Se regala, se repite y se recomienda, y por eso no tiene precio: no se entrega, se cumple. La oferta es lo que esa misma persona recibe a cambio de un pago, y eso ya se puede escribir en una hoja: qué recibe, para cuándo, por cuánto y qué pasa si no le sirve. Una promesa sin oferta es una charla bonita que deja a todo el mundo contento y no paga el internet. Una oferta sin promesa es un catálogo: técnicamente correcto y sin ningún motivo para abrirlo. La pregunta que convierte la primera en la segunda es una sola: ¿qué recibe exactamente por su dinero? Si la respuesta se puede envolver, ya hay oferta; si solo se puede contar, todavía es una charla."},{"q":"¿Para qué sirve el «no incluye» y cómo se escribe uno que funcione?","ans":"El «no incluye» es la mitad de la oferta que casi nadie escribe y la que evita casi todos los pleitos, porque lo que no está escrito ahí se va a pedir gratis y se va a dar por vergüenza. Se saca preguntándose qué es lo que van a pedir después, cuando ya pagaron y ya hay confianza: imprimir las copias del aula, cambiar el contenido a pedido, una capacitación presencial, que se conteste por WhatsApp a medianoche, fichas de otro grado. Y hay un detalle que lo cambia todo: cada línea del «no incluye» lleva su precio al lado. Así deja de ser una negativa seca y pasa a ser una venta, y uno puede decir que sí a todo sin regalar nada. No se escribe para protegerse del cliente: se escribe para poder trabajar tranquilo con él el resto del año."},{"q":"Una ficha costó doce horas de trabajo y L 90 de internet y energía. Explica de dónde sale el precio y por qué no es la suma de las horas.","ans":"Esas doce horas y esos L 90 son el piso de costo, y el piso sirve para una sola cosa: saber por debajo de qué cifra no se vende. No es el precio. El precio sale de lo que vale para quien paga, y a la maestra que compra esa ficha lo que le vale son las cuatro noches al mes que no se queda preparando clase, el libro de apoyo que no tiene que comprar y la clase de mañana resuelta hoy. Cobrar por horas tiene además un castigo escondido: al que aprendió a hacerla en cuatro horas le tocaría cobrar menos que al que tardó doce, o sea que trabajar mejor sale más barato. Y desvía la conversación, que pasa a ser sobre el tiempo del que cobra en vez de sobre el resultado del que paga. Por eso la ficha suelta vale L 30 y el aula L 250 al mes: son cifras de valor, con el costo abajo asegurando que no se pierde."},{"q":"Una red de tres centros suma veinte aulas y pide la mitad de precio, de L 250 a L 125 por aula. ¿Qué se contesta y por qué?","ans":"No se acepta ni se rechaza completo: se contraoferta. La cifra puede ser L 150 por aula, o sea L 3.000 al mes en vez de L 5.000, pero quitando la ficha nueva a pedido, el soporte por WhatsApp y el acompañamiento, y cobrando el año entero por adelantado, que son L 30.000 en febrero. La regla de fondo es que se baja el precio quitando algo, siempre, y se escribe qué se quitó. Un descuento que no quita alcance no es un descuento: es el precio nuevo, y el siguiente cliente lo va a saber, porque el mercado se entera. Si se aceptan los L 125 con todo incluido, al mes siguiente el centro de seis aulas que paga L 250 lo va a reclamar con toda la razón, y ahí ya no hay precio de lista: hay una negociación distinta con cada quien y una agenda llena de reclamos."},{"q":"Explica la escalera de la oferta de M.E.T.A.S y cuándo el escalón gratis se vuelve un problema.","ans":"Son tres escalones. El gratis: tres fichas completas y las misiones abiertas, sin cuenta ni instalación, que existe para probar sin riesgo. El básico: el aula al mes, L 250, que resuelve el problema completo de una maestra. Y el completo: el centro, L 1.200 al mes por seis aulas, con constancias y reportes, que es para quien ya confía y por eso no se le ofrece a nadie en la primera conversación. El gratis se vuelve problema el día que le alcanza a alguien para resolver el año entero: ahí deja de ser prueba y pasa a ser el producto, y el de pago se muere solo, no por malo sino por falta de motivo. La señal de alarma no es cuánta gente usa lo gratis, es que en tres meses nadie haya subido de escalón. Al gratis le tiene que faltar cobertura, nunca calidad: si lo gratis se ve malo, lo que se rompe es la promesa."},{"q":"Escribe la oferta de una página de M.E.T.A.S con sus ocho campos, y di qué regla de las cinco reglas de la oferta sostiene cada parte.","ans":"Resultado: la maestra llega el lunes con la clase lista sin haberla preparado de noche. Entregable: ficha de diez páginas en PDF con su pauta, más la misión abierta en el teléfono. Alcance: una materia, un grado y un tema por ficha, y todas las fichas del grado si es por aula. No incluye: impresión, cambios de contenido a pedido, capacitación presencial ni soporte fuera de horario, y aquí manda la primera regla, que lo que no está escrito ahí se va a pedir gratis. Plazo: lo publicado hoy, ficha nueva a pedido diez días hábiles, misión a la medida veinte. Precio y forma de pago: ficha L 30, aula L 250 al mes, seis aulas L 1.200, misión a la medida L 4.500, cobro por adelantado del 1 al 5; aquí mandan dos reglas, que el costo es el piso y que quien dice la primera cifra pone el ancla. Prueba: tres fichas completas gratis, el Campeonísimo funcionando y una maestra que lo dice con su nombre. Salida: treinta días, se devuelve el mes cobrado y se cancela sin explicaciones. Y encima de todo la quinta regla, que es la que autoriza a cobrar sin culpa: lo que no se paga solo se apaga."}];
let ansVisible=false;
function genTask(){sfx('click');const type=document.getElementById('tgType').value;const count=parseInt(document.getElementById('tgCount').value);ansVisible=false;const out=document.getElementById('tgOut');out.innerHTML='';if(type==='identify')genIdentifyTask(out,count);else if(type==='classify')genClassifyTask(out,count);else if(type==='complete')genCompleteTask(out,count);else if(type==='explain')genExplainTask(out,count);fin('s-tareas');}
function _instrBlock(out,title,lines){const ib=document.createElement('div');ib.className='tg-instruction-block';ib.innerHTML=`<h4>📋 ${title}</h4>`+lines.map(l=>`<p>${l}</p>`).join('');out.appendChild(ib);}
function genIdentifyTask(out,count){_instrBlock(out,'Instrucción',['Copia en tu cuaderno; subraya, colorea o encierra el concepto técnico ilustrado en cada oración. Escribe al lado de qué concepto se trata.','<strong>Ejemplo:</strong> Un solo contraejemplo basta para refutar una ley. → <span style="color:var(--jade);font-weight:700;">Falsacionismo</span>']);_pick(identifyTaskDB,Math.min(count,identifyTaskDB.length)).forEach((item,i)=>{const div=document.createElement('div');div.className='tg-task';div.innerHTML=`<div class="tg-task-num">${i+1}</div><div class="tg-task-content"><strong>${item.s}</strong><div style="border-bottom:1.5px solid var(--border);min-width:220px;margin-top:0.5rem;height:1.3rem;">&nbsp;</div><div class="tg-answer">✅ ${item.type}</div></div>`;out.appendChild(div);});}
function genClassifyTask(out,count){_instrBlock(out,'Instrucción',['Copia la siguiente tabla en tu cuaderno. Para cada elemento, completa su tipo, características, ámbito y función.']);const items=_pick(classifyTaskDB,Math.min(count,classifyTaskDB.length));const wrap=document.createElement('div');wrap.style.overflowX='auto';const th=(t,extra='')=>`<th style="padding:0.3rem 0.4rem;border:1px solid var(--border);font-size:0.72rem;text-align:center;${extra}">${t}</th>`;let html=`<table style="width:100%;border-collapse:collapse;font-size:0.78rem;min-width:520px;"><thead><tr style="background:var(--pri-gl);">${th('Elemento','text-align:left;')}${th('Tipo')}${th('Características')}${th('Ámbito')}${th('Función')}</tr></thead><tbody>`;items.forEach(it=>{html+=`<tr><td style="padding:0.4rem 0.5rem;border:1px solid var(--border);font-weight:600;">${it.w}</td>`+Array(4).fill(`<td style="padding:0.4rem;border:1px solid var(--border);min-width:50px;"></td>`).join('')+'</tr>';});html+='</tbody></table>';wrap.innerHTML=html;out.appendChild(wrap);const ans=document.createElement('div');ans.className='tg-answer';ans.style.marginTop='0.8rem';ans.innerHTML='<strong>✅ Respuestas:</strong><br>'+items.map(it=>`<strong>${it.w}:</strong> Tipo: ${it.gen} | Características: ${it.n} | Ámbito: ${it.g} | Función: ${it.t}`).join('<br>');out.appendChild(ans);}
function genCompleteTask(out,count){_instrBlock(out,'Instrucción',['Copia y resuelve en tu cuaderno. Cada oración tiene un espacio ___. Elige y escribe la opción correcta.']);const pool=_shuffle([...completeTaskDB]);for(let i=0;i<count;i++){const item=pool[i%pool.length];const div=document.createElement('div');div.className='tg-task';const sent=item.s.replace('___','<span class="tg-blank" style="min-width:90px;">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</span>');div.innerHTML=`<div class="tg-task-num">${i+1}</div><div class="tg-task-content"><strong>${sent}</strong><div style="margin-top:0.4rem;font-size:0.82rem;color:var(--gray);">📝 Opciones: <strong>${item.opts.join(' | ')}</strong></div><div class="tg-answer">✅ ${item.ans}</div></div>`;out.appendChild(div);}}
function genExplainTask(out,count){_instrBlock(out,'Instrucción',['Copia las siguientes preguntas en tu cuaderno y responde cada una de forma clara y argumentada.']);const pool=_shuffle([...explainQuestions]);for(let i=0;i<count;i++){const item=pool[i%pool.length];const div=document.createElement('div');div.className='tg-task';div.innerHTML=`<div class="tg-task-num">${i+1}</div><div class="tg-task-content"><strong>${item.q}</strong><div style="border-bottom:1.5px solid var(--border);min-width:200px;margin-top:0.5rem;height:1.3rem;">&nbsp;</div><div style="border-bottom:1.5px solid var(--border);min-width:200px;margin-top:0.3rem;height:1.3rem;">&nbsp;</div><div class="tg-answer">✅ ${item.ans}</div></div>`;out.appendChild(div);}}
function toggleAns(){ansVisible=!ansVisible;document.querySelectorAll('.tg-answer').forEach(el=>el.style.display=ansVisible?'block':'none');sfx('click');}

