function evalSwitchMode(mode){
  sfx('click');
  const cWrap=document.getElementById('evalConceptWrap'),critWrap=document.getElementById('evalCritWrap');
  const cBtn=document.getElementById('evalModeBtnConcept'),critBtn=document.getElementById('evalModeBtnCrit');
  if(mode==='crit'){
    cWrap.style.display='none';critWrap.style.display='block';
    cBtn.classList.remove('active');cBtn.setAttribute('aria-selected','false');
    critBtn.classList.add('active');critBtn.setAttribute('aria-selected','true');
    if(!window._evalCritData)genEvalCrit();
  }else{
    critWrap.style.display='none';cWrap.style.display='block';
    critBtn.classList.remove('active');critBtn.setAttribute('aria-selected','false');
    cBtn.classList.add('active');cBtn.setAttribute('aria-selected','true');
  }
}

const critCaseBank=[{"txt":"Una maestra de sexto vio la ficha de fracciones y quiere solo esa, hoy, para la clase de mañana. Pregunta cuánto es y aclara que paga de su bolsillo."},{"txt":"Una directora de un centro de seis aulas pide usar las misiones con todos sus grados y pregunta cuánto sería al mes. Hasta hoy no había ningún precio escrito."},{"txt":"Un negocio de la zona ofrece L 8.000 por poner su logo en la portada de todas las fichas durante un año. Es dinero contante y el dueño es conocido de la familia."},{"txt":"Una editorial ofrece L 60.000 de pago único por cuarenta fichas ya hechas, con su sello en la portada. Es más dinero del que el proyecto ha visto junto."},{"txt":"Un centro pide una misión sobre la historia de su municipio, hecha a la medida, con sus fotos y sus nombres. Preguntan cuánto y para cuándo."},{"txt":"Una red de tres centros suma veinte aulas y pide la mitad de precio: de L 250 a L 125 por aula. Dicen que por volumen es lo justo y que si no, no hay trato."},{"txt":"Una página educativa con cuarenta mil seguidores ofrece tres publicaciones sobre M.E.T.A.S a cambio de las fichas gratis para su comunidad. Insisten en que es una vitrina."},{"txt":"Una empresa de publicidad ofrece L 0,90 por cada mil anuncios mostrados dentro de la aplicación, unos L 1.800 al mes, con la condición de que todo quede gratis para siempre."}];
const critCaseQuestions=["1. ¿Qué se entrega exactamente y qué NO se incluye?","2. ¿Cuál es el piso de costo y de dónde sale el precio que pones?","3. Escribe en 3-4 frases la oferta que le contestarías, por escrito.","4. ¿Cuál es el plazo, la forma de pago y la salida si no sirve?"];
const critCaseGuides=["Se nombra el entregable en algo que se pueda tocar y comprobar, y el «no incluye» línea por línea, con su precio al lado. Lo que no aparezca ahí se va a pedir gratis, y se va a dar por vergüenza.","El piso sale del presupuesto real: horas, internet, energía. Marca el mínimo y nada más, porque el costo es el piso, nunca el precio. El precio sale de lo que la persona se ahorra o gana, y se dice primero: quien dice la primera cifra pone el ancla.","La oferta se escribe, no se improvisa por teléfono: resultado, entregable, alcance con su «no incluye», plazo, precio con fecha de cobro, prueba y salida. Y casi ninguna oferta se acepta o se rechaza completa: se acepta con condiciones pensadas en frío.","Plazo con fecha y qué pasa si se atrasa; cobro por adelantado del 1 al 5, por un medio que deje recibo; salida escrita, con plazo y sin letra chica. Sin salida, todo el riesgo lo carga quien paga, y por eso muchos no llegan a pagar."];

const critErrorBank=[{"txt":"\"Se lo dejo en lo que usted crea justo\".","g1":"«Lo que usted crea justo» suena generoso y es lo más caro que existe: el otro dice la primera cifra y esa cifra queda de ancla para todos los que vengan detrás.","g2":"Se dice la primera cifra uno mismo, decidida en frío antes de que suene el teléfono, y se enseña la oferta completa con lo que incluye y lo que no."},{"txt":"\"Le cobro por las horas: son doce horas de trabajo por ficha\".","g1":"Cobrar por horas castiga al que trabaja rápido y bien, y pone la conversación sobre el tiempo del que cobra en vez de sobre el resultado del que paga.","g2":"Las horas sirven para sacar el piso de costo. El precio se saca de lo que la maestra se ahorra: cuatro noches al mes valen más que doce horas de trabajo ajeno."},{"txt":"\"Se lo dejo a mitad de precio, total son veinte aulas\".","g1":"Un descuento que no quita alcance no es un descuento: es el precio nuevo, y el siguiente cliente lo va a saber porque el mercado se entera.","g2":"Se baja el precio quitando algo, y se escribe qué se quitó: L 150 por aula sin ficha a pedido, sin soporte y sin acompañamiento, con el año por adelantado."},{"txt":"\"El paquete incluye todo lo que el centro necesite\".","g1":"«Todo lo que necesiten» no tiene fondo. Sin «no incluye» escrito, el trabajo extra se hace «por esta vez» y queda de costumbre.","g2":"Cinco líneas de «no incluye» con su precio al lado: impresión, cambios de contenido, capacitación presencial, soporte fuera de horario y fichas de otro grado. Así cada negativa se vuelve una venta."},{"txt":"\"Devoluciones no hay: el material ya se descargó\".","g1":"Sin salida escrita, todo el riesgo de la primera compra lo carga quien paga, y ese miedo es lo que frena casi todas las primeras compras.","g2":"Treinta días: si no sirvió, se devuelve el mes cobrado y se cancela sin pedir explicaciones. Lo ya descargado se lo queda, que cuesta cero y compra confianza."},{"txt":"\"Nos pagan con visibilidad, y eso hoy vale más que el dinero\".","g1":"La visibilidad no paga el internet ni la energía, y regalar el catálogo delante de cuarenta mil personas deja el precio en cero para todas ellas.","g2":"Se acepta como pago en especie con precio puesto: tres publicaciones valoradas en L 6.000 por tres fichas y un mes de una sola aula, con enlace al sitio propio."}];

const critDecisionBank=["Una maestra quiere solo la ficha de fracciones para mañana: ¿se le cobra por unidad o se le regala como prueba, y qué se le dice del aula?","Seis aulas al mes y ningún precio escrito todavía: ¿qué cifra se dice primero y qué se quita para poder sostenerla?","L 8.000 por el logo en la portada durante un año: ¿qué se cede, qué no se cede ni por L 30.000 y qué se contraoferta?","L 60.000 por cuarenta fichas con exclusividad: ¿qué cuenta hay que hacer antes de contestar y qué licencia se acepta?","Misión a la medida por L 4.500: ¿cuántas rondas de cambios entran en el precio y qué pasa si el contenido del centro llega tarde?","Veinte aulas a mitad de precio o no hay trato: ¿qué se quita para bajar de L 250 y qué condición de pago se agrega?","Tres publicaciones a cambio del catálogo entero: ¿en cuánto se valora esa visibilidad y qué parte de la oferta se entrega?","Anuncios por L 1.800 al mes con todo gratis para siempre: llena la oferta de una página de ese trato y decide si se acepta y con qué límites."];
const critDecisionGuide="La decisión correcta casi nunca es aceptar completo ni rechazar de plano: es aceptar con condiciones, y las condiciones se piensan en frío, no con alguien enfrente esperando una firma. El orden: se nombra qué se entrega y qué NO se incluye, línea por línea y con precio al lado; se saca el piso de costo del presupuesto real y se fija el precio por lo que vale para quien paga, no por las horas, porque el costo es el piso y nunca el precio; se dice la primera cifra, porque quien dice la primera cifra pone el ancla; si piden rebaja, se baja el precio quitando alcance y se escribe qué se quitó; y se cierra con plazo, forma de pago con fecha y salida escrita. Vale más una oferta chica cobrada que un trato grande que deja el escalón de pago en cero, porque lo que no se paga solo se apaga.";

const critCompareBank=[{"a":"Cobrar la ficha suelta a L 30, con el precio escrito en el sitio.","b":"Regalar la ficha suelta a quien la pida y ya se verá después.","ga":"Caso A: fija el precio de referencia de toda la línea y deja abierta la puerta al aula de L 250 al mes.","gb":"Caso B: el precio queda en cero para esa maestra y para las tres a las que se lo cuente, y subirlo después cuesta el doble."},{"a":"Bajar a L 150 por aula quitando la ficha a pedido y el soporte.","b":"Bajar a L 125 por aula dejando el paquete igual.","ga":"Caso A: el descuento se paga con alcance y se le puede explicar a cualquier otro cliente sin quedar mal.","gb":"Caso B: no es descuento, es el precio nuevo. El centro de seis aulas que paga L 250 lo va a reclamar con toda la razón."},{"a":"El logo del patrocinador en la contraportada por L 8.000 al año.","b":"El logo del patrocinador en la portada por L 8.000 al año.","ga":"Caso A: se cobra un espacio que estaba vacío sin tocar lo que decide la lectura del material.","gb":"Caso B: la portada es donde la maestra decide en dos segundos si esto es material educativo o publicidad. Ahí el precio no es el espacio."},{"a":"Licencia no exclusiva por dos años a la editorial, con el nombre del autor en la portada.","b":"Vender las cuarenta fichas con exclusividad por L 60.000.","ga":"Caso A: entra el dinero y entra la distribución, y el proyecto sigue vendiendo las mismas fichas por unidad y por aula.","gb":"Caso B: L 60.000 no es el precio de cuarenta fichas: es el precio de todo lo que esas fichas iban a producir en cinco años."}];

const critCauseBank=[{"cause":"Se contesta «lo que usted crea justo» cuando preguntan el precio.","guide":"El otro dice la primera cifra y esa cifra queda de ancla. Subirla después parece un abuso, aunque sea lo que de verdad cuesta."},{"cause":"No se escribe el «no incluye».","guide":"Lo que no está escrito se pide gratis y se da por vergüenza. El trabajo extra se hace «por esta vez» y al mes siguiente ya es costumbre."},{"cause":"El precio se saca sumando las horas de trabajo.","guide":"Se castiga al que trabaja rápido y bien, y la conversación pasa a ser sobre el tiempo del que cobra en vez de sobre el resultado del que paga."},{"cause":"Se da un descuento sin quitar nada del alcance.","guide":"El descuento se vuelve el precio nuevo para todos, porque el mercado se entera. El precio de lista deja de existir ese mismo día."},{"cause":"El escalón gratis alcanza para resolver el año entero.","guide":"Deja de ser prueba y pasa a ser el producto. El de pago se muere solo, y no por malo sino por falta de motivo para subir."},{"cause":"La oferta se cierra sin escribir la salida.","guide":"Todo el riesgo de la primera compra lo carga quien paga. Y cada reclamo se negocia de cero, con el cliente enojado enfrente."}];
const critEffectBank=[{"effect":"La maestra pagó los L 30 sin pedir rebaja y volvió por el aula completa.","guide":"El precio estaba escrito en el sitio y no se negoció caso por caso. La ficha suelta es la puerta, no el negocio."},{"effect":"El centro aceptó L 1.200 al mes y nadie pidió más de lo pactado.","guide":"El «no incluye» estaba escrito y con precio al lado. El descuento existía porque el alcance bajó, no porque el cliente insistió."},{"effect":"Se dijo que no a los L 8.000 por la portada y el patrocinador firmó la contraportada.","guide":"Había una contraoferta lista, con tamaño y plazo escritos. Decir que no con una alternativa en la mano no cierra la puerta."},{"effect":"La misión a la medida se entregó a los veinte días y se cobró completa.","guide":"Las rondas de cambios estaban contadas, la tercera tenía precio y el contenido histórico lo entregaba el centro por escrito."},{"effect":"La red de veinte aulas pagó el año entero por adelantado en febrero.","guide":"Se bajó de L 250 a L 150 quitando ficha a pedido, soporte y acompañamiento. La rebaja se pagó con alcance y con caja por delante."},{"effect":"Con cuarenta mil personas mirando, el escalón de pago siguió existiendo.","guide":"La visibilidad entró como pago en especie con precio puesto y alcance limitado: tres fichas y un aula, no el catálogo entero."}];

function genEvalCrit(){
  sfx('click');
  _injectFormaSel('genEvalCrit','evalCritFormaSel',evalCritFormNum,function(v){evalCritFormNum=v;});const _sC=document.getElementById('evalCritFormaSel');if(_sC&&parseInt(_sC.value,10))evalCritFormNum=Math.min(EVAL_FORMAS,Math.max(1,parseInt(_sC.value,10)));const cf=evalCritFormNum;window._currentEvalCritForm=cf;const rngC=_evalRng(200000+cf);evalCritFormNum=(evalCritFormNum%EVAL_FORMAS)+1;_injectFormaSel('genEvalCrit','evalCritFormaSel',evalCritFormNum,function(v){evalCritFormNum=v;});saveProgress();
  document.getElementById('evalcrit-screen-title').textContent=`🧠 Cuánto cobro por esto · Forma ${cf} · La oferta · Ruta de la Marca`;
  evalCritAnsVisible=false;
  const out=document.getElementById('evalCritOut');out.innerHTML='';

  const kase=_rotaF(critCaseBank,cf);
  const s1=document.createElement('div');
  s1.innerHTML=`<div class="eval-section-title">I. Simulacro de Presión: la interpelación <span class="eval-pts">20 pts</span></div><div class="eval-item"><div class="crit-scenario">${kase.txt}</div>${critCaseQuestions.map((q,i)=>`<div class="crit-q-block"><div class="crit-q-label">${q}</div><textarea class="crit-textarea" rows="2" aria-label="${q}"></textarea><div class="crit-pauta">${critCaseGuides[i]}</div></div>`).join('')}<div class="crit-selfscore"><label for="critScore0">Obtenido:</label><input type="number" id="critScore0" class="crit-score-input" data-score="0" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s1);

  const err=_rotaF(critErrorBank,cf);
  const s2=document.createElement('div');
  s2.innerHTML=`<div class="eval-section-title">II. Corrige el error <span class="eval-pts">20 pts</span></div><div class="eval-item"><div class="crit-scenario">${err.txt}</div><p style="font-size:0.85rem;margin-bottom:0.5rem;">Identifica <strong>dos errores</strong> y corrígelos con tus propias palabras:</p><div class="crit-q-block"><div class="crit-q-label">Error 1 y su corrección:</div><textarea class="crit-textarea" rows="2" aria-label="Error 1 y su corrección"></textarea><div class="crit-pauta">${err.g1}</div></div><div class="crit-q-block"><div class="crit-q-label">Error 2 y su corrección:</div><textarea class="crit-textarea" rows="2" aria-label="Error 2 y su corrección"></textarea><div class="crit-pauta">${err.g2}</div></div><div class="crit-selfscore"><label for="critScore1">Obtenido:</label><input type="number" id="critScore1" class="crit-score-input" data-score="1" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s2);

  const dec=_rotaF(critDecisionBank,cf);
  const s3=document.createElement('div');
  s3.innerHTML=`<div class="eval-section-title">III. Toma de decisiones bajo presión <span class="eval-pts">20 pts</span></div><div class="eval-item"><div class="crit-scenario">${dec}</div><div class="crit-q-block"><div class="crit-q-label">¿Qué se entrega exactamente, qué NO se incluye, a qué precio y con qué condición por escrito aceptarías? Explica por qué tu salida es mejor que aceptar completo o que rechazar de plano.</div><textarea class="crit-textarea" rows="4" aria-label="Recomendación y justificación"></textarea><div class="crit-pauta">${critDecisionGuide}</div></div><div class="crit-selfscore"><label for="critScore2">Obtenido:</label><input type="number" id="critScore2" class="crit-score-input" data-score="2" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s3);

  const cmp=_rotaF(critCompareBank,cf);
  const s4=document.createElement('div');
  s4.innerHTML=`<div class="eval-section-title">IV. Comparación razonada <span class="eval-pts">20 pts</span></div><div class="eval-item"><div class="crit-compare-grid"><div class="crit-compare-box"><h5>Caso A</h5>${cmp.a}</div><div class="crit-compare-box"><h5>Caso B</h5>${cmp.b}</div></div><div class="crit-q-block"><div class="crit-q-label">1. ¿Qué gana cada caso y cuál aguanta un cambio de funcionario? 2. ¿Por qué no son el mismo caso?</div><textarea class="crit-textarea" rows="4" aria-label="Comparación razonada de los casos A y B"></textarea><div class="crit-pauta">Caso A: ${cmp.ga} · Caso B: ${cmp.gb} · ${cmp.gr}</div></div><div class="crit-selfscore"><label for="critScore3">Obtenido:</label><input type="number" id="critScore3" class="crit-score-input" data-score="3" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s4);

  const causes=_pickF(critCauseBank,2,rngC),effects=_pickF(critEffectBank,3,rngC);
  let ceRows='';
  causes.forEach((it,i)=>{ceRows+=`<div class="crit-ce-item"><div class="crit-ce-row"><div class="crit-ce-cell crit-ce-given"><span class="crit-ce-tag">Causa</span>${it.cause}</div><div class="crit-ce-cell"><span class="crit-ce-tag">Efecto</span><textarea class="crit-textarea" rows="2" aria-label="Efecto de: ${it.cause}" placeholder="Escribe el efecto..."></textarea></div></div><div class="crit-pauta">${it.guide}</div></div>`;});
  effects.forEach((it,i)=>{ceRows+=`<div class="crit-ce-item"><div class="crit-ce-row"><div class="crit-ce-cell"><span class="crit-ce-tag">Causa</span><textarea class="crit-textarea" rows="2" aria-label="Causa de: ${it.effect}" placeholder="Escribe la causa..."></textarea></div><div class="crit-ce-cell crit-ce-given"><span class="crit-ce-tag">Efecto</span>${it.effect}</div></div><div class="crit-pauta">${it.guide}</div></div>`;});
  const s5=document.createElement('div');
  s5.innerHTML=`<div class="eval-section-title">V. Análisis de causas y efectos <span class="eval-pts">20 pts</span></div><div class="eval-item">${ceRows}<div class="crit-selfscore"><label for="critScore4">Obtenido:</label><input type="number" id="critScore4" class="crit-score-input" data-score="4" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s5);

  window._evalCritData={kase,err,dec,cmp,causes,effects};
  const totalPanel=document.createElement('div');totalPanel.id='evalCritTotalResult';totalPanel.className='crit-total-panel';totalPanel.innerHTML='<strong>🧮 Autoevaluación:</strong> responde cada sección, compara con la <em>Pauta</em> y anota tu puntaje (0–20) en cada casilla. Luego presiona <em>Calcular Total</em>.';out.appendChild(totalPanel);
  fin('s-evaluacion');
}
function toggleEvalCritAns(){evalCritAnsVisible=!evalCritAnsVisible;document.querySelectorAll('#evalCritOut .crit-pauta').forEach(el=>el.style.display=evalCritAnsVisible?'block':'none');sfx('click');}
function calcCritTotal(){
  if(!window._evalCritData){showToast('⚠️ Genera una prueba primero');return;}
  sfx('click');
  let total=0;
  document.querySelectorAll('#evalCritOut .crit-score-input').forEach(inp=>{let v=parseInt(inp.value)||0;v=Math.max(0,Math.min(20,v));inp.value=v;total+=v;});
  const panel=document.getElementById('evalCritTotalResult');
  if(panel){panel.className='crit-total-panel '+(total>=70?'eval-auto-pass':'eval-auto-risk');panel.innerHTML=`<strong>Puntaje total autoevaluado: ${total}/100</strong><br><em>Compara siempre tus respuestas con la Pauta antes de anotar el puntaje de cada sección.</em>`;}
  const formKey='crit_'+(window._currentEvalCritForm||1);
  if(total>=70){if(!xpTracker.wgt.has(formKey)){xpTracker.wgt.add(formKey);pts(8);}showToast('🎯 Cuánto cobro por esto: '+total+'/100');}
  else showToast('🧮 Puntaje registrado: '+total+'/100. ¡Sigue practicando!');
}
function printEvalCrit(){
  if(!window._evalCritData){showToast('⚠️ Genera una prueba primero');return;}
  sfx('click');
  const forma=window._currentEvalCritForm||1;const d=window._evalCritData;
  const lines=(n)=>Array(n).fill('<div class="ln"></div>').join('');
  let s1=`<div class="sec-title"><span>I. Simulacro de Presión: la interpelación</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div><p class="crit-print-scenario">${d.kase.txt}</p>`;
  critCaseQuestions.forEach(q=>{s1+=`<p class="crit-print-q">${q}</p>${lines(1)}`;});
  let s2=`<div class="sec-title"><span>II. Corrige el error</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div><p class="crit-print-scenario">${d.err.txt}</p><p class="crit-print-q">Identifica dos errores y corrígelos con tus propias palabras:</p><p class="crit-print-q"><strong>Error 1:</strong></p>${lines(1)}<p class="crit-print-q"><strong>Error 2:</strong></p>${lines(1)}`;
  let s3=`<div class="sec-title"><span>III. Toma de decisiones bajo presión</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div><p class="crit-print-scenario">${d.dec}</p><p class="crit-print-q">¿Qué se entrega exactamente, qué NO se incluye, a qué precio y con qué condición por escrito aceptarías? Explica por qué tu salida es mejor que aceptar completo o que rechazar de plano.</p>${lines(2)}`;
  let s4=`<div class="sec-title"><span>IV. Comparación razonada</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div><div class="crit-compare-print-grid"><div class="crit-compare-print-box"><strong>Caso A:</strong> ${d.cmp.a}</div><div class="crit-compare-print-box"><strong>Caso B:</strong> ${d.cmp.b}</div></div><p class="crit-print-q">1. ¿Qué gana cada caso y cuál aguanta un cambio de funcionario? 2. ¿Por qué no son el mismo caso?</p>${lines(2)}`;
  let ceTbl='<table class="crit-print-tbl"><tr><th>Causa</th><th>Efecto</th></tr>';
  d.causes.forEach(it=>{ceTbl+=`<tr><td>${it.cause}</td><td></td></tr>`;});
  d.effects.forEach(it=>{ceTbl+=`<tr><td></td><td>${it.effect}</td></tr>`;});
  ceTbl+='</table>';
  let s5=`<div class="sec-title"><span>V. Análisis de causas y efectos</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div>${ceTbl}`;
  let pR='';
  pR+=`<div class="p-sec"><div class="p-ttl">I. Caso</div>${critCaseQuestions.map((q,i)=>`<div class="p-crit-line"><strong>${i+1}.</strong> ${critCaseGuides[i]}</div>`).join('')}</div>`;
  pR+=`<div class="p-sec"><div class="p-ttl">II. Corrige el error</div><div class="p-crit-line"><strong>Error 1:</strong> ${d.err.g1}</div><div class="p-crit-line"><strong>Error 2:</strong> ${d.err.g2}</div></div>`;
  pR+=`<div class="p-sec"><div class="p-ttl">III. Toma de decisiones</div><div class="p-crit-line">${critDecisionGuide}</div></div>`;
  pR+=`<div class="p-sec"><div class="p-ttl">IV. Comparación</div><div class="p-crit-line"><strong>Caso A:</strong> ${d.cmp.ga}</div><div class="p-crit-line"><strong>Caso B:</strong> ${d.cmp.gb}</div><div class="p-crit-line">${d.cmp.gr}</div></div>`;
  pR+=`<div class="p-sec" style="grid-column:1/-1;"><div class="p-ttl">V. Causas y efectos</div>${d.causes.map(it=>`<div class="p-crit-line"><strong>Causa:</strong> ${it.cause} → <strong>Efecto:</strong> ${it.guide}</div>`).join('')}${d.effects.map(it=>`<div class="p-crit-line"><strong>Efecto:</strong> ${it.effect} → <strong>Causa:</strong> ${it.guide}</div>`).join('')}</div>`;
  const doc=`<!DOCTYPE html><html lang="es"><head><meta charset="UTF-8"><title>Cuánto cobro por esto · La oferta · Ruta de la Marca · Forma ${forma}</title><style>*{margin:0;padding:0;box-sizing:border-box;}body{font-family:Arial,Helvetica,sans-serif;font-size:11pt;color:#111;background:#fff;padding:1mm 5mm;}.ph{margin-bottom:0.3rem;}.ph h2{font-size:11pt;font-weight:700;text-align:center;margin-bottom:0.2rem;}.ph-line{display:flex;align-items:baseline;gap:5px;margin-bottom:3px;}.ph-fill{flex:1;border-bottom:1px solid #555;min-height:12px;display:block;}.ph-m{display:inline-block;min-width:80px;border-bottom:1px solid #555;}.ph-s{display:inline-block;min-width:52px;border-bottom:1px solid #555;}.ph-xs{display:inline-block;min-width:36px;border-bottom:1px solid #555;}.ph-crit{font-size:9.5pt;text-align:center;color:#555;margin-top:0.1rem;}.sec-title{font-size:10.5pt;font-weight:700;padding:0.1rem 0.4rem;margin:0.2rem 0 0.1rem;display:flex;justify-content:space-between;align-items:center;border-left:4px solid #3b3a86;background:#ece9fb;color:#3b3a86;}.obt-row{display:flex;align-items:baseline;gap:4px;font-size:9.5pt;font-weight:700;font-style:italic;color:#3b3a86;}.obt-lbl{white-space:nowrap;}.obt-line{display:inline-block;min-width:50px;border-bottom:1.5px solid #3b3a86;height:12px;}.obt-pct{white-space:nowrap;}.crit-print-scenario{font-size:10.5pt;background:#ece9fb;border-left:3px solid #3b3a86;padding:0.2rem 0.5rem;margin:0.1rem 0 0.2rem;line-height:1.3;}.crit-print-q{font-size:10pt;font-weight:600;margin:0.15rem 0 0.08rem;line-height:1.25;}.ln{border-bottom:1px solid #111;min-height:12px;margin-bottom:2px;}.crit-compare-print-grid{display:grid;grid-template-columns:1fr 1fr;gap:0.5rem;margin:0.15rem 0;}.crit-compare-print-box{font-size:9.5pt;background:#ece9fb;border-radius:4px;padding:0.25rem 0.4rem;line-height:1.25;}.crit-print-tbl{width:100%;border-collapse:collapse;font-size:9.5pt;margin-top:0.15rem;}.crit-print-tbl th,.crit-print-tbl td{border:1px solid #999;padding:0.3rem 0.45rem;text-align:left;height:30px;vertical-align:middle;}.crit-print-tbl th{background:#ece9fb;}.pauta-wrap{page-break-before:always;padding-top:0.4rem;}.p-head{border-bottom:2px solid #333;padding-bottom:0.3rem;margin-bottom:0.4rem;text-align:center;}.p-main{font-size:9.5pt;font-weight:700;}.p-sub{font-size:7pt;color:#c00;font-weight:700;margin:0.08rem 0;}.p-meta{font-size:7pt;color:#555;}.p-grid{display:grid;grid-template-columns:1fr 1fr;gap:0.4rem 0.9rem;}.p-sec{border:1px solid #ccc;border-radius:4px;padding:0.3rem 0.45rem;}.p-ttl{font-size:8pt;font-weight:700;border-bottom:1px solid #ddd;padding-bottom:0.1rem;margin-bottom:0.18rem;}.p-crit-line{font-size:7.5pt;color:#007a00;margin-bottom:0.18rem;line-height:1.35;}.total-row{display:flex;align-items:baseline;justify-content:flex-start;margin-left:20%;gap:7px;font-size:11pt;font-weight:700;font-style:italic;margin-top:0.2rem;padding:0.1rem 0;color:#3b3a86;}.total-row .obt-line{min-width:80px;border-bottom:1.5px solid #3b3a86;}.forma-tag{font-size:7pt;color:#555;border:1px solid #bbb;padding:1px 5px;border-radius:3px;background:white;}.print-foot{position:fixed;bottom:2mm;left:0;right:0;display:flex;align-items:center;justify-content:space-between;gap:8px;font-size:7.5pt;color:#111;background:#fff;padding:1px 3px;}.pf-item{display:inline-flex;align-items:center;gap:4px;}.pf-line{display:inline-block;width:26mm;border-bottom:1px solid #333;}.pf-box{display:inline-block;width:3.4mm;height:3.4mm;border:1px solid #333;}@media print{@page{size:letter portrait;margin:12.7mm;}}</style></head><body><div class="ph"><h2>Evaluación Competencial · Cuánto cobro por esto · La oferta · Ruta de la Marca · Autocapacitación Técnica</h2><div class="ph-line"><strong>Nombre:</strong><span class="ph-fill">&nbsp;</span><strong>Fecha:</strong><span class="ph-m">&nbsp;</span></div><div class="ph-line"><strong>Institución:</strong><span class="ph-fill">&nbsp;</span><strong>Grado y Sección:</strong><span class="ph-s">&nbsp;</span><strong>Nº Lista:</strong><span class="ph-xs">&nbsp;</span></div><p class="ph-crit">Valor total: 100 puntos · 5 secciones de 20 puntos</p></div>${s1}${s2}${s3}${s4}${s5}<div class="total-row"><span>Total, obtenido</span><span class="obt-line"></span><span>de 100</span></div><div class="pauta-wrap"><div class="p-head"><div class="p-main">✅ PAUTA: Cuánto cobro por esto · La oferta · Ruta de la Marca · Forma ${forma}</div><div class="p-sub">Documento exclusivo del docente · No distribuir al estudiante</div><div class="p-meta">Valor total: 100 pts | 5 secciones × 20 pts c/u, respuesta abierta, usar como guía de corrección</div></div><div class="p-grid">${pR}</div></div><div class="print-foot"><span class="pf-item"><strong>Nº de Evaluación temática realizada:</strong><span class="pf-line">&nbsp;</span></span><span class="pf-item"><strong>Evaluación con valor en el parcial</strong><span class="pf-box"></span></span><span class="pf-item"><strong>Evaluación solo de repaso</strong><span class="pf-box"></span></span><span class="forma-tag">Forma ${forma}</span></div></body></html>`;
  const win=window.open('','_blank','');
  if(!win){showToast('⚠️ Activa las ventanas emergentes para imprimir');return;}
  win.document.write(doc);win.document.close();setTimeout(()=>win.print(),400);
}

// ===================== LÍNEA DE TIEMPO INTERACTIVA =====================
const timelineData=[{"y":"1","icon":"🎯","label":"El resultado","text":"¿Qué queda distinto en la vida de quien paga? <strong>Decide:</strong> si el precio parece caro o barato, porque caro se mide contra el resultado y no contra el trabajo. <strong>Se rompe:</strong> al describir lo que hace el producto en vez de lo que le pasa a la persona. <strong>En M.E.T.A.S:</strong> la maestra llega el lunes con la clase lista sin haberla preparado de noche."},{"y":"2","icon":"📦","label":"El entregable","text":"¿Qué recibe exactamente y en qué forma? <strong>Decide:</strong> si se puede comprobar que se entregó. <strong>Se rompe:</strong> con entregables que no se pueden tocar, como «acompañamiento» o «acceso a la plataforma». <strong>En M.E.T.A.S:</strong> un PDF de diez páginas con su pauta, más la misión abierta en el teléfono."},{"y":"3","icon":"📏","label":"El alcance y el no incluye","text":"¿Hasta dónde llega esto y dónde se acaba? <strong>Decide:</strong> cuánto trabajo cabe dentro del mismo precio. <strong>Se rompe:</strong> al escribir solo lo que sí incluye, porque lo que no está escrito se pide gratis y se da por vergüenza. <strong>En M.E.T.A.S:</strong> una materia, un grado y un tema por ficha; no incluye impresión, ni cambios a pedido, ni capacitación presencial."},{"y":"4","icon":"📅","label":"El plazo","text":"¿Para cuándo, y qué pasa si se atrasa? <strong>Decide:</strong> si el resultado llega a tiempo de servir. <strong>Se rompe:</strong> con «cuando esté listo», que pierde la confianza sin haber cobrado un peso de más. <strong>En M.E.T.A.S:</strong> lo publicado se descarga hoy; una ficha nueva a pedido, diez días hábiles."},{"y":"5","icon":"💵","label":"El precio y la forma de pago","text":"¿Cuánto, cuándo se cobra y en qué forma? <strong>Decide:</strong> si el proyecto sigue existiendo el año que viene. <strong>Se rompe:</strong> al sacar el precio del costo en vez de sacarlo de lo que vale para quien paga, y al no decir la fecha de cobro. <strong>En M.E.T.A.S:</strong> L 30 la ficha suelta, L 250 el aula al mes, cobrado por adelantado del 1 al 5."},{"y":"6","icon":"🧾","label":"La prueba","text":"¿Por qué creerte antes de pagarte? <strong>Decide:</strong> si llega a haber una primera compra. <strong>Se rompe:</strong> con adjetivos en lugar de cosas que se puedan abrir hoy mismo. <strong>En M.E.T.A.S:</strong> tres fichas completas abiertas y gratis, el Campeonísimo funcionando y una maestra que lo dice con su nombre."},{"y":"7","icon":"🚪","label":"La salida","text":"¿Qué pasa si no sirve? <strong>Decide:</strong> cuánto riesgo carga el que paga, que es lo que frena casi todas las primeras compras. <strong>Se rompe:</strong> cuando no está escrita y cada reclamo se negocia de cero, con el cliente enojado enfrente. <strong>En M.E.T.A.S:</strong> treinta días; si no sirvió, se devuelve el mes cobrado y se cancela sin pedir explicaciones."}];
function initTimeline(){const track=document.getElementById('timelineTrack');if(!track)return;timelineData.forEach((d,i)=>{const b=document.createElement('button');b.className='tl-node';b.type='button';b.dataset.idx=i;b.innerHTML=`<span class="tl-dot">${d.icon}</span><span class="tl-year">${d.y}</span><span class="tl-label">${d.label}</span>`;b.onclick=()=>showTimeline(i);track.appendChild(b);});}
function showTimeline(i){const d=timelineData[i];document.querySelectorAll('.tl-node').forEach(n=>n.classList.remove('tl-active'));document.querySelector(`.tl-node[data-idx="${i}"]`).classList.add('tl-active');document.getElementById('tlInfoIcon').textContent=d.icon;document.getElementById('tlInfoText').innerHTML=`<strong>${d.y} · ${d.label}.</strong> ${d.text}`;document.getElementById('tlInfo').style.display='flex';sfx('click');}

// ===================== SIMULACIÓN: MÉTODO DE POPPER =====================
let methodRunning=false;
function startMethod(){if(methodRunning)return;methodRunning=true;sfx('click');document.getElementById('methodBtn').style.display='none';document.getElementById('methodBranch').classList.remove('show');document.getElementById('methodResult').innerHTML='';const steps=['ms1','ms2','ms3','ms4'];const arrows=['ma1','ma2','ma3'];steps.forEach(s=>document.getElementById(s).classList.remove('active','done'));arrows.forEach(a=>document.getElementById(a).classList.remove('active'));let i=0;function next(){if(i>0){document.getElementById(steps[i-1]).classList.remove('active');document.getElementById(steps[i-1]).classList.add('done');}if(i<steps.length){if(i>0)document.getElementById(arrows[i-1]).classList.add('active');document.getElementById(steps[i]).classList.add('active');sfx('ok');i++;setTimeout(next,900);}else{document.getElementById('methodBranch').classList.add('show');}}next();}
function resolveMethod(conInternet){sfx(conInternet?'ok':'no');document.getElementById('methodBranch').classList.remove('show');document.getElementById('ms4').classList.remove('active');document.getElementById('ms4').classList.add('done');const r=document.getElementById('methodResult');if(conInternet){r.innerHTML='<div class="method-step done" style="opacity:1;"><span class="ms-num">5</span><span class="ms-icon">🛡️</span><span class="ms-text"><strong>Pediste 24 horas:</strong> la presión se corta en seco y la conversación pasa del sentimiento a los números.</span></div><div class="method-arrow active" style="margin:0.4rem 0;">⬇️</div><div class="method-step done" style="opacity:1;"><span class="ms-num">6</span><span class="ms-icon">📄</span><span class="ms-text"><strong>Al día siguiente decides tú:</strong> si el plazo era real, la oferta sigue en pie y ahora con condiciones tuyas. Si se cayó, la presión era el producto.</span></div>';}else{r.innerHTML='<div class="method-step done" style="opacity:1;border-color:var(--red);background:var(--red-gl);"><span class="ms-num">5</span><span class="ms-icon">✍️</span><span class="ms-text"><strong>Contestaste en caliente:</strong> el sí salió con la emoción alta y sin comparar nada.</span></div><div class="method-arrow active" style="margin:0.4rem 0;">⬇️</div><div class="method-step done" style="opacity:1;"><span class="ms-num">6</span><span class="ms-icon">🔗</span><span class="ms-text"><strong>Y la coherencia lo amarra:</strong> ese sí pequeño se cobra después con uno más grande. No fue tonto: fue una decisión tomada en el peor momento posible.</span></div>';}methodRunning=false;document.getElementById('methodBtn').style.display='inline-flex';document.getElementById('methodBtn').textContent='🔄 Repetir simulación';sfx('fan');}

// ===================== LABORATORIO DE CONCEPTOS =====================
const parteData={"alcance":{"nombre":"El alcance","icon":"📏","estructura":{"title":"Qué es","info":"• Hasta dónde llega lo que se entrega y <strong>dónde se acaba</strong><br>• Tiene dos mitades: el «sí incluye» y el <strong>«no incluye»</strong><br>• La segunda mitad es la que casi nadie escribe y la que evita los pleitos"},"funcion":{"title":"Cómo se escribe","info":"• Se cuenta en unidades que el otro entienda: una ficha, un aula, un mes<br>• El «no incluye» se saca preguntando <strong>qué es lo que van a pedir después</strong><br>• Cada línea del «no incluye» tiene su precio aparte, no es una negativa seca"},"enfermedades":{"title":"Dónde se rompe","info":"• Con «y cualquier ajuste que necesite», que no tiene fondo<br>• Cuando el trabajo extra se hace «por esta vez» y queda de costumbre<br>• Al describir el alcance en horas propias en vez de en resultados del otro"},"cuidados":{"title":"Cómo está en M.E.T.A.S","info":"• Una <strong>materia, un grado y un tema</strong> por ficha, con su pauta<br>• No incluye: impresión, cambios de contenido a pedido, capacitación presencial ni soporte fuera de horario<br>• Cada una de esas líneas tiene precio propio, y por eso se puede decir que sí"}},"precio":{"nombre":"El precio","icon":"💵","estructura":{"title":"Qué es","info":"• La cifra que se cobra y <strong>cuándo se cobra</strong><br>• No es el costo: el costo es el piso, y el precio sale de lo que vale para quien paga<br>• Sin forma de pago escrita, el precio es un deseo"},"funcion":{"title":"Cómo se escribe","info":"• Primero el piso, que sale del presupuesto real (la ruta hermana)<br>• Después el valor: qué se ahorra o gana la persona que paga<br>• Se dice <strong>la primera cifra</strong> y se escribe la fecha de cobro y el medio"},"enfermedades":{"title":"Dónde se rompe","info":"• Al cotizar sumando horas, que castiga al que trabaja rápido y bien<br>• Al esperar que el otro diga la cifra: la primera que se dice <strong>ancla</strong> todas las demás<br>• Con descuentos que no quitan nada, que se convierten en el precio nuevo"},"cuidados":{"title":"Cómo está en M.E.T.A.S","info":"• Ficha suelta <strong>L 30</strong> · aula <strong>L 250 al mes</strong> · centro de seis aulas <strong>L 1.200 al mes</strong><br>• Misión a la medida <strong>L 4.500</strong>, mitad al encargar y mitad al entregar<br>• Cobro por adelantado del 1 al 5, por transferencia o en efectivo con recibo"}},"prueba":{"nombre":"La prueba","icon":"🧾","estructura":{"title":"Qué es","info":"• Lo que hace creíble la oferta <strong>antes</strong> de que alguien pague<br>• Se puede abrir, tocar o comprobar hoy, sin pedir permiso<br>• No es un adjetivo: es un objeto o una persona con nombre"},"funcion":{"title":"Cómo se escribe","info":"• Se eligen tres pruebas de tipos distintos: algo que se abre, algo que funciona y alguien que lo dice<br>• Los números van <strong>reales y con fecha</strong>, aunque sean chicos<br>• La prueba se pone <strong>antes</strong> del precio, nunca después"},"enfermedades":{"title":"Dónde se rompe","info":"• Con cifras que nadie puede comprobar, que derriban hasta lo que sí era cierto<br>• Cuando el escalón gratis es tan grande que ya nadie necesita pagar<br>• Al esconder la prueba detrás de un registro o un correo de confirmación"},"cuidados":{"title":"Cómo está en M.E.T.A.S","info":"• <strong>Tres fichas completas</strong> abiertas y gratis, sin cuenta ni instalación<br>• El <strong>Campeonísimo</strong> funcionando, no prometido<br>• Una maestra que ya lo usó y lo dice con su nombre y su centro"}},"salida":{"nombre":"La salida","icon":"🚪","estructura":{"title":"Qué es","info":"• Qué pasa <strong>si no sirve</strong>: devolución, cambio o cancelación<br>• Es la pieza que quita el miedo de la primera compra<br>• Escrita, con plazo y sin condiciones escondidas"},"funcion":{"title":"Cómo se escribe","info":"• Un plazo corto y claro, y <strong>qué se devuelve exactamente</strong><br>• Se dice quién decide (el que paga, no el que cobra)<br>• Se deja escrito qué se queda el cliente aunque cancele"},"enfermedades":{"title":"Dónde se rompe","info":"• Cuando no existe y cada reclamo se pelea de cero<br>• Con letra chica que la anula, que sale más cara que no ofrecerla<br>• Al usarla como excusa para no arreglar el trabajo mal hecho"},"cuidados":{"title":"Cómo está en M.E.T.A.S","info":"• <strong>Treinta días</strong>: si no sirvió, se devuelve el mes cobrado y se cancela<br>• No se pide explicación ni se retiene lo ya descargado<br>• La ficha que ya imprimió se la queda: cuesta cero y compra confianza"}}};
let labParte='alcance',labAspecto='estructura';
function labShowParte(parteKey){labParte=parteKey;updateLabDisplay();document.querySelectorAll('.lab-cont-btn').forEach(b=>b.classList.remove('active-pri'));const btn=document.querySelector(`[data-parte="${parteKey}"]`);if(btn)btn.classList.add('active-pri');if(typeof sfx==='function')sfx('click');}
function labShowAspecto(aspectoKey){labAspecto=aspectoKey;updateLabDisplay();document.querySelectorAll('.lab-asp-btn').forEach(b=>b.classList.remove('active-sec'));const btn=document.querySelector(`[data-aspecto="${aspectoKey}"]`);if(btn)btn.classList.add('active-sec');if(typeof sfx==='function')sfx('click');}
function updateLabDisplay(){const data=parteData[labParte];const asp=data[labAspecto];document.getElementById('lab-sentence').innerHTML=`🦉 Explorando: <strong>${data.nombre}</strong> → <strong>${asp.title}</strong>`;document.getElementById('lab-display').innerHTML=`<div class="lab-cont-header">${data.icon} ${data.nombre}</div><div class="lab-asp-title">${asp.title}</div><div class="lab-asp-info">${asp.info}</div>`;}

// ===================== DIPLOMA =====================
function _diplPct(){return xp>=MXP?100:Math.round((xp/MXP)*100);}
function openDiploma(){sfx('fan');const pct=_diplPct();document.getElementById('diplPct').textContent=pct+'%';document.getElementById('diplBar').style.width=pct+'%';document.getElementById('diplDate').textContent='Fecha: '+new Date().toLocaleDateString('es-HN',{year:'numeric',month:'long',day:'numeric'});const msgs=['¡Sigue estudiando tu sistema!','¡Muy buen trabajo!','¡Excelente gestor en formación!','¡Sabes por dónde se mueve esto!','¡Estratega institucional!'];document.getElementById('diplMsg').textContent=msgs[Math.min(Math.floor(pct/25),4)];const stars=['⭐','⭐⭐','⭐⭐⭐'];document.getElementById('diplStars').textContent=stars[Math.min(Math.floor(pct/40),2)];const achTxt=unlockedAch.map(id=>ACHIEVEMENTS[id].icon+' '+ACHIEVEMENTS[id].label).join(' · ');document.getElementById('diplAch').textContent=achTxt||'Sigue completando secciones para desbloquear logros';document.getElementById('diplomaOverlay').classList.add('open');launchConfetti();}
function closeDiploma(){document.getElementById('diplomaOverlay').classList.remove('open');}
function updateDiplomaName(v){document.getElementById('diplName').textContent=v||'Estudiante';}
function shareWA(){const name=document.getElementById('diplName').textContent||'Estudiante';const pct=_diplPct();const msg='📈 ¡'+name+' completó la Etapa 2 de la Ruta de la Marca (La oferta: qué se entrega y a qué precio)! 🏅 Progreso: '+pct+'% · ⚙️ policastsapien.com';window.open('https://wa.me/?text='+encodeURIComponent(msg),'_blank');}
async function captureDiploma(){if(typeof html2canvas==='undefined'){showToast('⚠️ Cargando... intenta de nuevo');return;}sfx('click');const card=document.querySelector('.diploma-card');const btn=document.querySelector('.diploma-actions .btn-pri');const toHide=[card.querySelector('.diploma-input'),card.querySelector('.diploma-actions'),card.querySelector('hr')];if(btn){btn.disabled=true;btn.textContent='⏳ Capturando...';}toHide.forEach(el=>{if(el)el.style.display='none';});let dataUrl='';try{const canvas=await html2canvas(card,{scale:2,useCORS:true,backgroundColor:'#ffffff'});toHide.forEach(el=>{if(el)el.style.display='';});dataUrl=canvas.toDataURL('image/png');const name=(document.getElementById('diplName').textContent||'Estudiante').replace(/\s+/g,'-');const fileName='constancia-'+name+'.png';const cap=window.Capacitor;if(cap&&cap.isNativePlatform&&cap.isNativePlatform()&&cap.Plugins?.Filesystem&&cap.Plugins?.Share){const base64Data=dataUrl.split(',')[1];const result=await cap.Plugins.Filesystem.writeFile({path:fileName,data:base64Data,directory:'CACHE'});await cap.Plugins.Share.share({url:result.uri,dialogTitle:'Guardar / Compartir Constancia'});}else{const a=document.createElement('a');a.href=dataUrl;a.download=fileName;a.click();}}catch(e){toHide.forEach(el=>{if(el)el.style.display='';});if(e.name!=='AbortError')showToast('⚠️ No se pudo guardar la constancia');}finally{if(btn){btn.disabled=false;btn.textContent='📷 Guardar foto';}}}

